from collections import deque

def transform(grid):
    g=[r[:] for r in grid]; h=len(g); w=len(g[0])
    ones=[(i,j) for i in range(h) for j in range(w) if g[i][j]==1]
    # pair nearest aligned markers
    used=set(); pairs=[]; cands=[]
    for a in range(len(ones)):
        for b in range(a+1,len(ones)):
            (i1,j1),(i2,j2)=ones[a],ones[b]
            if i1==i2 or j1==j2:
                cands.append((abs(i1-i2)+abs(j1-j2),a,b))
    cands.sort()
    for dd,a,b in cands:
        if a not in used and b not in used:
            used.add(a); used.add(b); pairs.append((ones[a],ones[b]))
    lrows=set(); lcols=set()
    for (i1,j1),(i2,j2) in pairs:
        if i1==i2: lrows.add(i1)
        else: lcols.add(j1)
    seen=[[False]*w for _ in range(h)]; comps={}
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==2 and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                for c in comp: comps[c]=id(comp)
                comps[('comp',len(comps))]=comp
    # store comps list properly
    seen=[[False]*w for _ in range(h)]; clist=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True; comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and g[na][nb]==2 and not seen[na][nb]:
                            seen[na][nb]=True; q.append((na,nb))
                clist.append(comp)
    cell2comp={}
    for k,comp in enumerate(clist):
        for c in comp: cell2comp[c]=k
    recolor=set()
    for i,j in ones:
        # ray in 4 directions; stops at first block, recolors it
        for di,dj in ((0,1),(0,-1),(1,0),(-1,0)):
            a,b=i+di,j+dj
            while 0<=a<h and 0<=b<w and g[a][b]!=2:
                a+=di; b+=dj
            if 0<=a<h and 0<=b<w and g[a][b]==2:
                recolor.add(cell2comp[(a,b)])
    for k in recolor:
        for a,b in clist[k]: g[a][b]=1
    for i in lrows:
        for j in range(w): g[i][j]=1
    for j in lcols:
        for i in range(h): g[i][j]=1
    return g

